// Real BitTorrent on loopback with generated bytes; never shows windows or accesses browsers.
using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
using ShiyingDesktop;
class BtCheck {
    static readonly List<string> checks=new List<string>();
    static void Check(bool value,string name){if(!value)throw new Exception(name);checks.Add(name);Console.WriteLine("PASS "+name);}
    static bool Reject(Action action){try{action();return false;}catch{return true;}}
    static object Field(object target,string name){return target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(target);}
    static void Click(Button button){typeof(Button).GetMethod("OnClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(button,new object[]{EventArgs.Empty});}
    static Download Job(Manager manager,string id){return manager.Snapshot().Single(j=>j.Id==id);}
    static void Wait(Manager manager,Func<bool> done,string name,int seconds=90){var end=DateTime.UtcNow.AddSeconds(seconds);var report=DateTime.UtcNow;while(!done()&&DateTime.UtcNow<end){manager.Tick();var failed=manager.Snapshot().FirstOrDefault(j=>j.Status=="失败");if(failed!=null)throw new Exception(failed.Error);if(DateTime.UtcNow>report){Console.WriteLine("PROGRESS "+String.Join("; ",manager.Snapshot().Select(j=>j.Status+" "+j.Progress.ToString("0.0")+"% "+j.Stage)));report=DateTime.UtcNow.AddSeconds(10);}Thread.Sleep(80);}Check(done(),name);}
    static void Local(Manager manager,string files){manager.BtLocalOnly=true;manager.Config.Proxy="";manager.Config.Folder=files;}
    static void ReconnectAndFinish(string folder,string fixtures,string files,string seedRoot){
        var guard=typeof(Manager).GetMethod("BtPayloadVerified",BindingFlags.Static|BindingFlags.NonPublic);var test=new Download{BtSelected=new[]{1},Transfer=new TransferInfo{Total=100,Completed=100}};var state=new Dictionary<string,object>{{"seeder","false"}};
        Check(!(bool)guard.Invoke(null,new object[]{test,state}),"100 percent alone never authorizes early tracker cancellation");state["seeder"]="true";state["verifiedLength"]="100";Check(!(bool)guard.Invoke(null,new object[]{test,state}),"hash-checking cannot trigger completion cleanup");state.Remove("verifiedLength");state["verifyIntegrityPending"]="true";Check(!(bool)guard.Invoke(null,new object[]{test,state}),"pending verification cannot trigger completion cleanup");state.Remove("verifyIntegrityPending");Check((bool)guard.Invoke(null,new object[]{test,state}),"engine-confirmed verified selection may finish tracker cleanup");
        byte[] original=File.ReadAllBytes(Path.Combine(fixtures,"local.torrent"));byte[] hinted=TorrentInfo.WithPeerTracker(original,"http://127.0.0.1:1234/test");var before=TorrentInfo.Read(original);var after=TorrentInfo.Read(hinted);Check(before.Hash==after.Hash&&before.Private==after.Private&&before.Files.Select(f=>f.Path).SequenceEqual(after.Files.Select(f=>f.Path)),"loopback peer hint preserves raw info hash, private flag and file list");
        double reconnectSeconds,finishSeconds;using(var manager=new Manager(Path.Combine(folder,"cached-reconnect"))){
            Local(manager,files);manager.Config.RateKiB=512;var job=manager.ImportTorrent(Path.Combine(fixtures,"resume-once.torrent"));manager.SelectBtFiles(job.Id,new[]{1});Wait(manager,()=>job.Transfer.Completed>1048576,"one-shot tracker supplies initial real peer",30);manager.Pause(job.Id);Wait(manager,()=>job.Status=="已暂停","cached reconnect pause settles");
            var hints=(System.Collections.IDictionary)Field(manager,"btPeerHints");Check(hints.Count==1,"manual pause caches only recently connected peers in memory");long paused=job.Transfer.Completed;string sourceHash=ComponentStore.Hash(Path.Combine(manager.Work(job),"source.torrent"));string data=Path.Combine(job.BtFolder,job.BtFiles[0].Path.Replace('/',Path.DirectorySeparatorChar));using(var file=new FileStream(data,FileMode.Open,FileAccess.ReadWrite)){int b=file.ReadByte();file.Position=0;file.WriteByte((byte)(b^255));}
            manager.Config.RateKiB=0;var watch=System.Diagnostics.Stopwatch.StartNew();manager.Resume(job.Id);try{Wait(manager,()=>job.Transfer.Completed>paused+524288,"cached peer reconnect works when original tracker stops returning peers",20);}catch{Console.WriteLine("HINT REQUESTS "+manager.BtPeerHintRequests);var hintValue=hints[job.Id];Util.Atomic(Path.Combine(folder,"failed-loopback-hint.json"),new{body=Convert.ToBase64String((byte[])hintValue.GetType().GetField("Body").GetValue(hintValue)),state=Rpc(manager,"tellStatus",job.Id)});throw;}reconnectSeconds=watch.Elapsed.TotalSeconds;Wait(manager,()=>job.Status=="已完成","cached peer transfer finishes with corrupted paused bytes repaired",20);Verify(job,seedRoot);Check(ComponentStore.Hash(Path.Combine(manager.Work(job),"source.torrent"))==sourceHash,"cached reconnect never rewrites the saved original torrent");
            Check(manager.BtPeerHintRequests>0,"real engine consumes the loopback peer cache response");Check(!hints.Contains(job.Id)&&!File.Exists(Path.Combine(manager.Work(job),"recent-peers.json")),"completed task clears its optional persisted peer cache");
        }
        using(var manager=new Manager(Path.Combine(folder,"dead-cache-fallback"))){Local(manager,files);manager.Config.RateKiB=512;var job=manager.ImportTorrent(Path.Combine(fixtures,"local.torrent"));manager.SelectBtFiles(job.Id,new[]{1});Wait(manager,()=>job.Transfer.Completed>1048576,"fallback probe obtains genuine initial bytes",30);manager.Pause(job.Id);Wait(manager,()=>job.Status=="已暂停","fallback probe pause settles");long paused=job.Transfer.Completed;var hints=(System.Collections.IDictionary)Field(manager,"btPeerHints");var hint=hints[job.Id];int dead=Int32.Parse(File.ReadAllText(Path.Combine(fixtures,"dead-port.txt")));var body=new List<byte>(System.Text.Encoding.ASCII.GetBytes("d8:intervali2e5:peers6:"));body.AddRange(new byte[]{127,0,0,1,(byte)(dead>>8),(byte)dead});body.AddRange(System.Text.Encoding.ASCII.GetBytes("6:peers60:e"));hint.GetType().GetField("Body").SetValue(hint,body.ToArray());manager.Config.RateKiB=0;manager.Resume(job.Id);Wait(manager,()=>job.Transfer.Completed>paused+524288,"dead cached peer quickly falls back to the original live tracker",20);Wait(manager,()=>job.Status=="已完成","fallback transfer completes and keeps all selected bytes",20);Verify(job,seedRoot);}
        using(var manager=new Manager(Path.Combine(folder,"slow-tracker-finish"))){Local(manager,files);var job=manager.ImportTorrent(Path.Combine(fixtures,"slow-stop.torrent"));manager.SelectBtFiles(job.Id,new[]{1});Wait(manager,()=>job.Transfer.Total>0&&job.Transfer.Completed==job.Transfer.Total,"all selected pieces become verified before completion cleanup",30);var watch=System.Diagnostics.Stopwatch.StartNew();Wait(manager,()=>job.Status=="已完成","slow tracker stop response does not hold completion hostage",6);finishSeconds=watch.Elapsed.TotalSeconds;Verify(job,seedRoot);var rpc=(IDictionary<string,object>)Rpc(manager,"tellStatus",job.Id);Check(Util.Str(rpc,"status")=="complete","UI completion follows the engine terminal result and closed files");}
        Util.Atomic(Path.Combine(folder,"reconnect-finish-evidence.json"),new{ok=true,reconnectSeconds,finishSeconds,method="one-shot loopback tracker returns peers only once; cached peer reconnect and corrupt-file repair; dead cache falls back to original tracker; actual tracker requests delayed 12 seconds while local WebSeed provides selected bytes; engine terminal complete and SHA256 checked; no public peers or visible windows"});
    }
    static object Rpc(Manager manager,string method,string id=null){return typeof(Manager).GetMethod("BtRpc",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(manager,new object[]{method,id==null?new object[0]:new object[]{id}});}
    static void CacheAndReasonChecks(string folder,string torrent){
        using(var manager=new Manager(Path.Combine(folder,"cache-validation"))){Local(manager,Path.Combine(folder,"cache-files"));var job=manager.ImportTorrent(torrent);string path=Path.Combine(manager.Work(job),"recent-peers.json");var hints=(System.Collections.IDictionary)Field(manager,"btPeerHints");var load=typeof(Manager).GetMethod("LoadBtPeers",BindingFlags.Instance|BindingFlags.NonPublic);
            Func<Dictionary<string,object>> valid=()=>new Dictionary<string,object>{{"hash",job.BtHash},{"expires",DateTime.UtcNow.AddMinutes(9).Ticks.ToString()},{"ipv4",Convert.ToBase64String(new byte[]{127,0,0,1,12,34})},{"ipv6",""}};
            Util.Atomic(path,valid());load.Invoke(manager,new object[]{job});Check(hints.Contains(job.Id),"valid bound short-lived cache loads without starting the engine");hints.Clear();
            foreach(string kind in new[]{"wrong-hash","expired","future","base64","partial-endpoint","zero-port","too-many"}){var saved=valid();if(kind=="wrong-hash")saved["hash"]=new string('f',40);if(kind=="expired")saved["expires"]=DateTime.UtcNow.AddSeconds(-1).Ticks.ToString();if(kind=="future")saved["expires"]=DateTime.UtcNow.AddMinutes(11).Ticks.ToString();if(kind=="base64")saved["ipv4"]="bad!";if(kind=="partial-endpoint")saved["ipv4"]=Convert.ToBase64String(new byte[]{127});if(kind=="zero-port")saved["ipv4"]=Convert.ToBase64String(new byte[]{127,0,0,1,0,0});if(kind=="too-many")saved["ipv4"]=Convert.ToBase64String(Enumerable.Range(0,65).SelectMany(n=>new byte[]{127,0,0,1,12,34}).ToArray());Util.Atomic(path,saved);load.Invoke(manager,new object[]{job});Check(hints.Count==0,"optional peer cache safely rejected: "+kind);}
            foreach(string text in new[]{"{bad","null",new string('x',8193)}){File.WriteAllText(path,text);load.Invoke(manager,new object[]{job});Check(hints.Count==0&&File.ReadAllText(path)==text,"damaged or oversized peer cache is ignored and retained without touching tasks");}
            Check(job.Status=="等待选文件"&&Field(manager,"btAria")==null&&File.Exists(Path.Combine(manager.Work(job),"source.torrent")),"invalid caches cannot start an unselected payload or replace its torrent");
        }
        using(var manager=new Manager(Path.Combine(folder,"reason-ui"))){var job=manager.ImportTorrent(torrent);job.Status="下载中";job.BtPhase="content";var state=new Dictionary<string,object>{{"status","active"},{"downloadSpeed","0"},{"connections","0"}};var peers=new object[0];
            Action<string> expect=part=>{Check(job.BtReason.Contains(part),"download reason reflects confirmed state: "+part);typeof(Manager).GetMethod("PublishSnapshot",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(manager,null);using(var view=new DownloadDetailsWindow(manager,job.Id)){Check(!view.Visible&&((Label)Field(view,"notice")).Text.Contains(job.BtReason)&&((Label)Field(view,"notice")).Text.Contains(job.BtAdvice),"hidden details display reason and advice");}};
            Manager.ExplainBt(job,state,peers,0);expect("尚未发现");Check(!job.BtReason.Contains("故障")&&!job.BtAdvice.Contains("DHT 已被"),"zero peers do not invent a Tracker or DHT fault");state["verifiedLength"]="0";Manager.ExplainBt(job,state,peers,0);expect("正在校验");state.Remove("verifiedLength");state["verifyIntegrityPending"]="true";Manager.ExplainBt(job,state,peers,0);expect("等待文件校验");state.Remove("verifyIntegrityPending");state["status"]="waiting";Manager.ExplainBt(job,state,peers,0);expect("下载名额");state["status"]="active";job.BtPhase="metadata";Manager.ExplainBt(job,state,peers,0);expect("种子信息");job.BtPhase="content";state["downloadSpeed"]="1000000";Manager.ExplainBt(job,state,peers,1048576);expect("限速");Manager.ExplainBt(job,state,peers,0);expect("接收数据");state["downloadSpeed"]="0";state["connections"]="1";Manager.ExplainBt(job,state,new object[]{new Dictionary<string,object>{{"peerChoking","true"}}},0);expect("暂未开放");Manager.ExplainBt(job,state,new object[]{new Dictionary<string,object>{{"peerChoking","false"}}},0);expect("暂未收到");Manager.ExplainBt(job,state,peers,0);expect("等待下载源");Manager.ExplainBt(job,state,null,-1);expect("无法确认");job.Status="已暂停";typeof(Manager).GetMethod("PublishSnapshot",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(manager,null);using(var view=new DownloadDetailsWindow(manager,job.Id))Check(((Label)Field(view,"notice")).Text.Contains("已暂停")&&!view.Visible,"pause hides the old active reason without showing a window");
        }
    }
    static void RestartCacheStage(string stage,string folder,string fixtures,string seedRoot){
        string state=Path.Combine(folder,"restart-cache-state"),checkpoint=Path.Combine(folder,"restart-cache-checkpoint.json");
        if(stage=="restart-cache-save"){string id;using(var manager=new Manager(state)){Local(manager,Path.Combine(folder,"restart-cache-files"));manager.Config.RateKiB=512;var job=manager.ImportTorrent(Path.Combine(fixtures,"restart-once.torrent"));id=job.Id;manager.SelectBtFiles(id,new[]{1});Wait(manager,()=>job.Transfer.Completed>1048576&&job.Transfer.Completed<job.Transfer.Total,"first process obtains genuine partial data",30);Check(job.Status=="下载中","first process closes during active transfer without a manual pause");}var saved=Util.Json().Deserialize<List<Download>>(File.ReadAllText(Path.Combine(state,"tasks.json"))).Single();Check(saved.Id==id&&saved.Status=="已暂停"&&File.Exists(Path.Combine(state,"partial",id,"recent-peers.json")),"active shutdown saves a bound peer cache and paused task");Util.Atomic(checkpoint,new{id,pausedBytes=saved.Transfer.Completed});return;}
        var point=Util.Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(checkpoint));string jobId=Convert.ToString(point["id"]);long before=Convert.ToInt64(point["pausedBytes"]);using(var manager=new Manager(state)){Local(manager,Path.Combine(folder,"restart-cache-files"));var job=Job(manager,jobId);Check(job.Status=="已暂停"&&job.BtSelected.SequenceEqual(new[]{1})&&((System.Collections.IDictionary)Field(manager,"btPeerHints")).Count==0,"new OS process starts without inherited peer memory");string path=Path.Combine(job.BtFolder,job.BtFiles[0].Path.Replace('/',Path.DirectorySeparatorChar));using(var file=new FileStream(path,FileMode.Open,FileAccess.ReadWrite)){int value=file.ReadByte();file.Position=0;file.WriteByte((byte)(value^255));}manager.Config.RateKiB=0;var watch=System.Diagnostics.Stopwatch.StartNew();manager.Resume(jobId);Wait(manager,()=>Job(manager,jobId).Transfer.Completed>before+524288,"new process reconnects while original tracker has no more peers",20);double seconds=watch.Elapsed.TotalSeconds;Wait(manager,()=>Job(manager,jobId).Status=="已完成","new process finishes and repairs modified paused bytes",20);job=Job(manager,jobId);Verify(job,seedRoot);Check(manager.BtPeerHintRequests>0,"new process actually consumes persisted peers through its own loopback interface");Check(!File.Exists(Path.Combine(manager.Work(job),"recent-peers.json")),"completed restart clears only its temporary peer cache");Util.Atomic(Path.Combine(folder,"restart-cache-evidence.json"),new{ok=true,processId=System.Diagnostics.Process.GetCurrentProcess().Id,reconnectSeconds=seconds,checks=checks.ToArray(),method="separate OS processes; first exits during active transfer; second starts with no in-memory peers, original private tracker returns no peers, DHT/PEX disabled; selected file repaired and full SHA256 checked; no visible windows"});}
    }
    static void ProfileChecks(string folder){
        using(var manager=new Manager(Path.Combine(folder,"profiles"))){
            var args=(List<string>)typeof(Manager).GetMethod("BtArguments",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(manager,new object[]{1234,2345});
            Check(args.Contains("--dht-entry-point=dht.transmissionbt.com:6881")&&args.Any(a=>a.StartsWith("--dht-file-path6="))&&args.Contains("--rpc-listen-all=false"),"production profile bootstraps DHT, isolates routing caches and keeps RPC local without starting it");
            var options=typeof(Manager).GetMethod("BtOptions",BindingFlags.Instance|BindingFlags.NonPublic);var job=new Download{Id=new string('1',16),Kind="torrent",HasMetadata=true};
            var publicOptions=(Dictionary<string,string>)options.Invoke(manager,new object[]{job,folder});Check(publicOptions.ContainsKey("bt-tracker")&&publicOptions["bt-max-peers"]=="128"&&publicOptions["bt-request-peer-speed-limit"]=="5120K"&&publicOptions["bt-tracker-interval"]=="0","public profile adds bounded peer discovery and respects tracker announce intervals");
            job.BtPrivate=true;Check(!((Dictionary<string,string>)options.Invoke(manager,new object[]{job,folder})).ContainsKey("bt-tracker"),"private torrent never receives public fallback trackers");
            job.HasMetadata=false;job.BtPrivate=false;Check(!((Dictionary<string,string>)options.Invoke(manager,new object[]{job,folder})).ContainsKey("bt-tracker"),"unknown magnet metadata never receives public fallback trackers");
            manager.BtLocalOnly=true;args=(List<string>)typeof(Manager).GetMethod("BtArguments",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(manager,new object[]{1234,2345});Check(!args.Any(a=>a.StartsWith("--dht-entry-point"))&&args.Contains("--enable-dht=false")&&args.Contains("--enable-dht6=false")&&args.Contains("--enable-peer-exchange=false")&&args.Contains("--interface=127.0.0.1"),"ordinary regression disables all public discovery and binds sockets to loopback");
            Check(manager.Config.BtUploadKiB==512,"new BT upload budget is bounded at 512 KiB/s by default");manager.Config.BtUploadKiB=0;manager.SaveSettings();Check(manager.Config.BtUploadKiB==16,"BT upload budget cannot silently become unlimited");manager.Config.BtUploadKiB=999999;manager.SaveSettings();Check(manager.Config.BtUploadKiB==8192,"BT upload budget has a finite upper bound");manager.Config.BtUploadKiB=512;
            using(var view=new MainWindow(manager,true)){typeof(MainWindow).GetField("inspectDialog",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(view,new Action<Form>(form=>{Check(form.Controls.OfType<NumericUpDown>().Any(n=>n.Minimum==16&&n.Maximum==8192&&n.Value==512),"hidden settings expose the BT upload budget");form.Scale(new SizeF(1.5f,1.5f));Bounds(form);Check(!form.Visible,"settings inspection never shows a window");}));typeof(MainWindow).GetMethod("SettingsDialog",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(view,null);}
        }
        string legacy=Path.Combine(folder,"old-settings");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"settings.json"),"{\"Connections\":8,\"Proxy\":\"\"}");using(var manager=new Manager(legacy))Check(manager.Config.BtUploadKiB==512,"old settings inherit a bounded upload default without losing compatibility");
    }
    static void SchedulingChecks(string folder,string files,string torrent,string cold,string magnet,string seedRoot){
        using(var manager=new Manager(Path.Combine(folder,"scheduling"))){
            Local(manager,files);manager.Config.FileSlots=1;var waiting=manager.ImportTorrent(cold);manager.SelectBtFiles(waiting.Id,new[]{1});manager.Tick();manager.Tick();waiting.BtLastCompleted=0;waiting.BtProgressAt=DateTime.UtcNow.AddSeconds(-61);manager.Tick();Check(waiting.Status=="下载中"||waiting.Status=="等待下载","a lone cold torrent keeps searching without pointless pause cycles");
            var hot=manager.ImportTorrent(torrent);manager.SelectBtFiles(hot.Id,new[]{1});waiting.BtProgressAt=DateTime.UtcNow.AddSeconds(-61);manager.Tick();Check(waiting.Status=="等待节点"&&waiting.BtAutoWaiting&&hot.Status!="排队中","inactivity with a queued task yields the payload slot immediately");
            var paused=(IDictionary<string,object>)Rpc(manager,"tellStatus",waiting.Id);Check(Util.Str(paused,"status")=="paused","yield pauses the actual engine and preserves its GID");
            using(var view=new DownloadDetailsWindow(manager,waiting.Id)){Check(((Button)Field(view,"pause")).Enabled&&((Label)Field(view,"notice")).Text.Contains("自动重试")&&!view.Visible,"hidden details explain automatic retry and retain manual pause");}
            var watch=System.Diagnostics.Stopwatch.StartNew();Wait(manager,()=>hot.Status=="已完成","a live torrent finishes while the cold task is deferred",30);Verify(hot,seedRoot);Check(waiting.Status=="等待节点"&&waiting.BtSelected.SequenceEqual(new[]{1}),"deferral retains selected indices and does not override backoff");
            waiting.BtRetryAt=DateTime.UtcNow.AddSeconds(-1);manager.Tick();Check(!waiting.BtAutoWaiting&&(waiting.Status=="下载中"||waiting.Status=="等待下载"),"backoff expiry unpauses the same engine task without a GID conflict");
            manager.Forget(hot.Id);hot=manager.ImportTorrent(torrent);manager.SelectBtFiles(hot.Id,new[]{2});waiting.BtLastCompleted=0;waiting.BtProgressAt=DateTime.UtcNow.AddSeconds(-61);manager.Tick();Check(waiting.Status=="等待节点","a still unavailable task can yield again after a retry");manager.Pause(waiting.Id);waiting.BtRetryAt=DateTime.UtcNow.AddSeconds(-1);manager.Tick();Check(waiting.Status=="已暂停","manual pause suppresses all automatic retries");
            string tracker=magnet.Substring(magnet.IndexOf("&tr="));var first=manager.Add("magnet:?xt=urn:btih:"+new string('a',40)+tracker,"file");var second=manager.Add("magnet:?xt=urn:btih:"+new string('b',40)+tracker,"file");var third=manager.Add("magnet:?xt=urn:btih:"+new string('c',40)+tracker,"file");manager.Tick();Check(first.BtPhase=="metadata"&&second.BtPhase=="metadata"&&third.Status=="排队中","two metadata slots can work independently of the occupied payload slot");
            first.BtLastCompleted=0;first.BtProgressAt=DateTime.UtcNow.AddSeconds(-61);manager.Tick();Check(first.Status=="等待节点"&&third.BtPhase=="metadata","stalled metadata also yields fairly within its own bounded queue");
            manager.Config.BtUploadKiB=256;manager.SaveSettings();var global=(IDictionary<string,object>)Rpc(manager,"getGlobalOption");Check(TransferData.Number(global,"max-overall-upload-limit")==262144,"saving the BT upload budget updates the running engine");
            Util.Atomic(Path.Combine(folder,"queue-evidence.json"),new{ok=true,liveTaskSeconds=watch.Elapsed.TotalSeconds,method="real empty tracker and loopback seeder; test timestamps simulate 61 seconds of zero progress and expired backoff; real forcePause/unpause, payload and metadata queues; no public BT or visible windows"});
        }
        using(var manager=new Manager(Path.Combine(folder,"queue-fairness"))){Local(manager,files);manager.Config.FileSlots=1;var a=manager.ImportTorrent(cold);var b=manager.ImportTorrent(Path.Combine(Path.GetDirectoryName(cold),"cold2.torrent"));var c=manager.ImportTorrent(Path.Combine(Path.GetDirectoryName(cold),"cold3.torrent"));foreach(var job in new[]{a,b,c})manager.SelectBtFiles(job.Id,new[]{1});manager.Tick();manager.Tick();a.BtLastCompleted=0;a.BtProgressAt=DateTime.UtcNow.AddSeconds(-61);manager.Tick();Check(a.Status=="等待节点"&&b.Status!="排队中","first cold task yields to the next task in order");a.BtRetryAt=DateTime.UtcNow.AddSeconds(-1);manager.Tick();b.BtLastCompleted=0;b.BtProgressAt=DateTime.UtcNow.AddSeconds(-61);manager.Tick();Check(a.Status=="排队中"&&c.Status!="排队中"&&c.BtPhase=="content","retry joins queue tail so a third task cannot be starved");}
    }
    static void Bounds(Control parent){parent.PerformLayout();foreach(Control child in parent.Controls){Check(child.Left>=-2&&child.Top>=-2&&child.Right<=parent.ClientSize.Width+2&&child.Bottom<=parent.ClientSize.Height+2,"hidden selection layout inside parent: "+child.GetType().Name);if(child is Panel)Bounds(child);}}
    static IEnumerable<Control> Descendants(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var item in Descendants(child))yield return item;}}
    static void SelectionUi(Manager manager,string id){using(var view=new TorrentSelectionWindow(manager,id)){
        var grid=(DataGridView)Field(view,"files");var start=(Button)Field(view,"start");var summary=(Label)Field(view,"summary");
        Check(!view.Visible&&grid.Rows.Count==2&&!start.Enabled&&grid.Rows.Cast<DataGridViewRow>().All(r=>!(bool)r.Cells[0].Value),"hidden selector starts with no files selected and download disabled");
        grid.Rows[0].Cells[0].Value=true;Check(start.Enabled&&summary.Text.Contains("1 / 2")&&summary.Text.Contains("8 MiB"),"checkbox updates selected count and total immediately");
        Click(Descendants(view).OfType<Button>().Single(b=>b.Text=="全选"));Check(summary.Text.Contains("2 / 2")&&summary.Text.Contains("16 MiB"),"select all requires explicit user action");
        Click(Descendants(view).OfType<Button>().Single(b=>b.Text=="清空选择"));Check(!start.Enabled&&summary.Text.Contains("0 / 2"),"clear selection disables download again");
        Bounds(view);view.Size=view.MinimumSize;Bounds(view);view.Scale(new SizeF(1.5f,1.5f));Bounds(view);Check(!view.Visible,"selector layout checks never show a window");
    }}
    static void HiddenDetails(Manager manager,string id){using(var view=new DownloadDetailsWindow(manager,id)){
        view.RefreshInfo();var labels=(Label[])Field(view,"values");var grid=(DataGridView)Field(view,"grid");Check(!view.Visible&&labels[0].Text=="8 MiB"&&labels[4].Text.Contains("分块")&&grid.Rows.Count==2,"hidden BT details show selected size, resume and both file rows");
        Check(grid.Rows.Cast<DataGridViewRow>().Any(r=>r.Cells.Cast<DataGridViewCell>().Any(c=>Convert.ToString(c.Value)=="未选择")),"details explicitly mark unselected files");
        Click((Button)Field(view,"fileView"));Check(!view.Visible&&grid.Rows.Count>0&&grid.Columns[1].HeaderText=="文件位置","details switch to actual whole-torrent piece locations without a window");
    }}
    static void Verify(Download job,string seedRoot){
        Check(job.Status=="已完成"&&Directory.Exists(job.File),"completed selected task points to its dedicated output folder");
        foreach(var file in job.BtFiles.Where(f=>f.Selected)){string actual=Path.Combine(job.File,file.Path.Replace('/',Path.DirectorySeparatorChar)),expected=Path.Combine(seedRoot,file.Path.Replace('/',Path.DirectorySeparatorChar));Check(File.Exists(actual)&&ComponentStore.Hash(actual)==ComponentStore.Hash(expected),"selected file SHA256 matches local seed: "+file.Path);}
        Check(job.Transfer.Total==job.BtFiles.Where(f=>f.Selected).Sum(f=>f.Length)&&job.Transfer.Completed==job.Transfer.Total&&job.Progress==100,"BT totals and completion count only selected files");
    }
    static void VerifySkipped(Download job,bool boundary){foreach(var file in job.BtFiles.Where(f=>!f.Selected)){string path=Path.Combine(job.File,file.Path.Replace('/',Path.DirectorySeparatorChar));long bytes=File.Exists(path)?new FileInfo(path).Length:0;Check(boundary?file.Completed<65536&&bytes<file.Length:file.Completed==0&&bytes==0,"unselected file is not fully downloaded; only cross-piece boundary may be present");}}
    [STAThread] static int Main(string[] args){try{Console.OutputEncoding=new System.Text.UTF8Encoding(false);
        string folder=Path.GetFullPath(args[0]),torrent=Path.GetFullPath(args[1]),magnet=args[2],seedRoot=args[3],boundary=args[4],hash,name;var parsed=TorrentInfo.Read(File.ReadAllBytes(torrent));if(args.Length>8&&args[8].StartsWith("restart-cache-")){RestartCacheStage(args[8],folder,Path.GetDirectoryName(torrent),seedRoot);return 0;}if(args.Length>8&&args[8]=="reconnect-only"){ReconnectAndFinish(folder,Path.GetDirectoryName(torrent),Path.Combine(folder,"files"),seedRoot);return 0;}
