        foreach(string invalid in new[]{"magnet:?xt=urn:btmh:1220abcd","magnet:?xt=urn:btih:bad","magnet:?xt=urn:btih:"+parsed.Hash+"&tr=file%3A%2F%2FC%3A%2Fprivate","magnet:?xt=urn:btih:"+parsed.Hash+"&xt=urn:btih:"+new string('a',40)})Check(Reject(()=>TorrentInfo.Magnet(invalid,out hash,out name)),"malformed, conflicting or unsupported magnet refused");
        foreach(string file in Directory.GetFiles(Path.GetDirectoryName(torrent),"invalid-*.torrent"))Check(Reject(()=>TorrentInfo.Read(File.ReadAllBytes(file))),"unsafe torrent refused: "+Path.GetFileName(file));
        Check(Reject(()=>TorrentInfo.Read(new byte[TorrentInfo.MaxBytes+1])),"oversized metadata refused before parsing");
        string state=Path.Combine(folder,"torrent-state"),files=Path.Combine(folder,"downloads");string id,output;long paused;
        using(var manager=new Manager(state)){
            Local(manager,files);manager.Config.RateKiB=512;
            int before=manager.Snapshot().Count;Check(Reject(()=>manager.AddMany(magnet+"\nmagnet:?xt=urn:btih:bad","file",files))&&manager.Snapshot().Count==before,"invalid mixed batch adds no partial queue");
            var job=manager.ImportTorrent(torrent);id=job.Id;Check(job.BtFiles.Length==2&&job.BtSelected==null&&job.Status=="等待选文件"&&job.Transfer.Total<0&&job.BtHash==parsed.Hash,"torrent import validates list and waits for explicit selection");
            Check(Reject(()=>manager.Add(magnet,"file")),"duplicate pending infohash refused");Check(File.Exists(Path.Combine(manager.Work(job),"source.torrent")),"validated metadata cached independently of original source");
