            foreach(var invalid in new[]{new int[0],new[]{0},new[]{3},new[]{1,1},new[]{1,2,3}})Check(Reject(()=>manager.SelectBtFiles(id,invalid))&&job.Status=="等待选文件","invalid or empty selection never queues a download");
            SelectionUi(manager,id);
            using(var window=new MainWindow(manager,true)){
                var resume=(Button)Field(window,"resume");Check(!window.Visible&&resume.Text=="选择文件"&&resume.Enabled,"main window exposes selection action for waiting task without displaying it");
                int dialogs=0;typeof(MainWindow).GetField("inspectDialog",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,new Action<Form>(form=>{dialogs++;var kind=form.Controls.OfType<ComboBox>().First();Check(kind.Items.Count==5&&kind.SelectedIndex==4&&form.Controls.OfType<Label>().Any(l=>l.Text.Contains("未确认前")),"new torrent dialog explains selection before download");form.Dispose();}));window.NewDownload(new Dictionary<string,object>{{"url",torrent},{"kind","torrent"}});Check(dialogs==1&&!window.Visible,"new torrent dialog inspected without showing it");
            }
            manager.SelectBtFiles(id,new[]{1});Check(job.BtSelected.SequenceEqual(new[]{1})&&job.Transfer.Total==8388608&&job.Status=="排队中","selection queues only first file and reports its size");
            Wait(manager,()=>job.Transfer.Completed>1048576&&job.Transfer.Speed>0&&TransferData.Segments(job).Sum(s=>s.Completed)>0,"selected BT transfer reports real speed and pieces");HiddenDetails(manager,id);
            var options=(IDictionary<string,object>)Rpc(manager,"getOption",id);Check(Util.Str(options,"select-file")=="1"&&Util.Str(options,"bt-remove-unselected-file")=="false"&&Util.Str(options,"seed-time")=="0","engine receives explicit file indices, preserves other files and stops seeding on completion");
            Check(TransferData.Number(options,"bt-max-peers")==128&&TransferData.Number(options,"bt-request-peer-speed-limit")==524288&&TransferData.Number(options,"max-download-limit")==524288,"running engine uses bounded peer expansion while respecting the user's download limit");
            Check(Reject(()=>manager.SelectBtFiles(id,new[]{2})),"changing selection while active requires pause");
            manager.Pause(id);Wait(manager,()=>job.Status=="已暂停","selected BT pause reaches stable state");paused=job.Transfer.Completed;output=job.BtFolder;manager.SaveSettings();Check(paused>0&&paused<job.Transfer.Total&&Directory.GetFiles(output,"*.aria2",SearchOption.AllDirectories).Length>0,"paused selection preserves control file and partial bytes");
            manager.Resume(id);Wait(manager,()=>job.Transfer.Completed>paused+524288,"selected files continue within same application session");manager.Pause(id);Wait(manager,()=>job.Status=="已暂停","pause again before restart");paused=job.Transfer.Completed;
        }
