            manager.SelectBtFiles(id,new[]{2});Wait(manager,()=>Job(manager,id).Status=="已完成","completed task can explicitly switch to another selected file");job=Job(manager,id);Verify(job,seedRoot);Check(ComponentStore.Hash(first)==firstHash,"changing selection preserves already downloaded unselected files");
        }
