        using(var manager=new Manager(state)){Local(manager,files);var job=Job(manager,id);Check(job.Status=="等待选文件"&&job.BtFiles.All(f=>!f.Selected),"legacy unfinished task never inherits implicit download-all");manager.Resume(id);manager.Tick();Check(Field(manager,"btAria")==null&&Job(manager,id).Status=="等待选文件","legacy continue cannot bypass confirmation");}
        legacy[0].Status="已完成";Util.Atomic(taskPath,legacy);using(var manager=new Manager(state)){Check(Job(manager,id).BtSelected.SequenceEqual(new[]{1,2})&&Job(manager,id).Status=="已完成","legacy completed tasks retain their all-files history");}
        using(var manager=new Manager(Path.Combine(folder,"magnet-state"))){
            Local(manager,files);var job=manager.Add(magnet,"file");Check(job.Kind=="magnet"&&!job.HasMetadata,"ordinary link entry recognizes magnets");manager.Tick();Check(job.BtPhase=="metadata"&&job.Transfer.Total<0&&TransferData.Segments(job).Length==0,"magnet metadata phase invents no payload size or progress");
            Wait(manager,()=>job.HasMetadata&&job.Status=="等待选文件","magnet retrieves validated file list then waits for selection");
            for(int n=0;n<3;n++)manager.Tick();manager.Resume(job.Id);Check(String.IsNullOrEmpty(job.BtFolder)&&job.BtSelected==null&&job.Status=="等待选文件","metadata completion and continue cannot start unselected payload");
            using(var view=new TorrentSelectionWindow(manager,job.Id)){Check(!((Button)Field(view,"start")).Enabled&&!view.Visible,"magnet selector also defaults to none");}
            manager.SelectBtFiles(job.Id,new[]{2});Wait(manager,()=>job.Status=="已完成","magnet downloads only explicitly chosen second file");Verify(job,seedRoot);VerifySkipped(job,false);
            string completed=job.File;manager.Forget(job.Id);Check(Directory.Exists(completed),"removing record keeps selected payload");var again=manager.Add(magnet,"file");Wait(manager,()=>again.HasMetadata&&again.Status=="等待选文件","same hash can be re-added without stale metadata session");manager.Forget(again.Id);Check(manager.Snapshot().Count==0,"waiting-selection task can be removed without starting payload");
        }
        using(var manager=new Manager(Path.Combine(folder,"boundary-state"))){Local(manager,files);var job=manager.ImportTorrent(boundary);manager.SelectBtFiles(job.Id,new[]{1});Wait(manager,()=>job.Status=="已完成","cross-file piece boundary still finishes selected file");Verify(job,seedRoot);VerifySkipped(job,true);Check(job.Transfer.Total==8388731&&TransferData.Segments(job).Sum(s=>s.Length)==16777216,"boundary accounting separates selected file bytes from whole torrent piece locations");}
        using(var manager=new Manager(Path.Combine(folder,"delete-paused-state"))){Local(manager,files);manager.Config.RateKiB=512;var job=manager.ImportTorrent(torrent);manager.SelectBtFiles(job.Id,new[]{1});Wait(manager,()=>job.Transfer.Completed>1048576,"delete fixture receives generated local data");manager.Pause(job.Id);Wait(manager,()=>job.Status=="已暂停","delete fixture stops before removing files");string btOutput=job.BtFolder;manager.Forget(job.Id,true);Check(manager.Snapshot().Count==0&&!Directory.Exists(manager.Work(job))&&!Directory.Exists(btOutput)&&File.Exists(torrent),"deleting a real paused aria2 task releases the engine and removes only its fixture output");var unstarted=manager.ImportTorrent(torrent);manager.Forget(unstarted.Id,true);Check(manager.Snapshot().Count==0&&File.Exists(torrent),"unstarted task can be deleted while another BT engine session exists");}
        ReconnectAndFinish(folder,Path.GetDirectoryName(torrent),files,seedRoot);
        SchedulingChecks(folder,files,torrent,args[5],magnet,seedRoot);
        using(var manager=new Manager(Path.Combine(folder,"local-dht"))){Local(manager,files);manager.BtLocalDhtPort=Int32.Parse(args[6]);var job=manager.Add(args[7],"file");Wait(manager,()=>job.HasMetadata&&job.Status=="等待选文件","trackerless magnet finds a peer through an actual loopback DHT bootstrap",90);Check(!job.BtPrivate&&String.IsNullOrEmpty(job.BtFolder)&&job.BtSelected==null,"DHT metadata still waits for explicit file selection");manager.SelectBtFiles(job.Id,new[]{2});Wait(manager,()=>job.Status=="已完成","DHT-discovered task downloads only the selected file");Verify(job,seedRoot);VerifySkipped(job,false);Check(manager.BtPeerSearches==1&&manager.BtPeerHintRequests>0,"real engine consumes supplemental DHT peers through the existing loopback cache");}
